{
  "status": "SUPPORTED",
  "task_summary": "Locate fastening parts and tool from storage, attach them to the target assembly on the workbench, then return the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "target_assembly",
        "entity_kind": "OBJECT",
        "function": "The grey rectangular object with yellow accents sitting on the table that needs to be fastened.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "grey block",
          "assembly",
          "part"
        ],
        "required_properties": [
          "has mounting holes or slots",
          "sits on workbench"
        ]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "A physical part required to secure the target assembly (e.g., a bolt, pin, or connector).",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screw",
          "bolt",
          "pin",
          "connector"
        ],
        "required_properties": [
          "compatible with target_assembly",
          "can be inserted or secured"
        ]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "An implement used to apply the fastening action (e.g., screwdriver, wrench).",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "gripper",
          "tool"
        ],
        "required_properties": [
          "capable of driving fasteners"
        ]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The wooden table surface where the target assembly is located and where the tool must be returned.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table",
          "desk",
          "workbench"
        ],
        "required_properties": [
          "flat surface",
          "supports objects"
        ]
      },
      {
        "id": "storage_container",
        "entity_kind": "OBJECT",
        "function": "Closed structures (drawers, cabinet) that may contain the missing components.",
        "required_count": 3,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "cabinet",
          "drawer",
          "cupboard"
        ],
        "required_properties": [
          "closed",
          "accessible"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_001",
        "relation": "fastener_suits_target",
        "participant_roles": [
          "fastening_component",
          "target_assembly"
        ],
        "required": true
      },
      {
        "id": "relation_002",
        "relation": "tool_enables_action",
        "participant_roles": [
          "fastening_tool",
          "fastening_component"
        ],
        "required": true
      },
      {
        "id": "relation_003",
        "relation": "rests_on",
        "participant_roles": [
          "target_assembly",
          "workbench"
        ],
        "required": false
      }
    ],
    "operation_pairings": [
      {
        "id": "operation_001",
        "operation": "inspect_and_retrieve",
        "participant_roles": [
          "storage_container",
          "fastening_component",
          "fastening_tool"
        ],
        "operation_count": 3
      },
      {
        "id": "operation_002",
        "operation": "secure_fastening",
        "participant_roles": [
          "fastening_tool",
          "fastening_component",
          "target_assembly"
        ],
        "operation_count": 1
      },
      {
        "id": "operation_003",
        "operation": "deposit_tool",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "target_assembly": [
        {
          "label": "grey_block_with_yellow_accents",
          "visual_description": "Grey rectangular object with yellow elements sitting on the wooden table surface."
        }
      ],
      "storage_container": [
        {
          "label": "blue_cabinet",
          "visual_description": "Tall blue cabinet standing against the wall behind the table."
        },
        {
          "label": "left_drawer",
          "visual_description": "Blue drawer attached to the left side of the table legs."
        },
        {
          "label": "right_drawer",
          "visual_description": "Blue drawer attached to the right side of the table legs."
        }
      ],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "Wooden table with two drawers and legs."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue_cabinet",
        "visual_description": "Closed blue cabinet door.",
        "reason": "Closed structure behind the table likely contains stored parts or tools."
      },
      {
        "id": "left_drawer",
        "label": "left_drawer",
        "visual_description": "Closed drawer with white handle.",
        "reason": "Closed drawer under the table likely contains stored parts or tools."
      },
      {
        "id": "right_drawer",
        "label": "right_drawer",
        "visual_description": "Closed drawer with white handle.",
        "reason": "Closed drawer under the table likely contains stored parts or tools."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "left_drawer",
      "right_drawer"
    ]
  }
